-- TEC-22 Pass, set and play + TEC-23 Pass and press (insert o aggiornamento)
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013e', '{"code":"TEC-22","title":"Pass, set and play – combinazione con manichino","area":"tecnica","fase":["attivazione"],"obiettivi":["passaggio","ricezione","uno-due","controllo orientato","postura del corpo"],"eta":"U9-U13","giocatori":"6-8 (2 stazioni)","spazio":"20x12 m","durata":10,"materiale":"2 paletti, 2 manichini, 4 cinesini, palloni","perche":"Attivazione con palla: qualità del passaggio, appoggio di ritorno (set), attacco dello spazio per ricevere in corsa e passaggio diagonale. Alza ritmo e intensità prima della parte centrale.","descrizione":"Setup: area 20x12 m con 2 stazioni. In ogni stazione una porta al centro formata da un paletto e un manichino (il manichino sul lato verso l’altra stazione), un cinesino a sinistra e uno a destra.\nEsecuzione: il giocatore a sinistra (9) passa attraverso la porta al compagno di fronte (5); 5 appoggia di ritorno nella stessa porta. 9 gioca il pallone all’esterno del manichino e 5 attacca lo spazio e lo riceve in corsa. 5 conduce e gioca in diagonale al giocatore a sinistra dell’altra stazione (11), poi segue il passaggio. Nella seconda stazione la stessa sequenza riparte nella direzione opposta (11 con 7) e la diagonale torna alla prima stazione.\nEsercizio continuo, ritmo alto.","rotazione":"Segui il passaggio: chi passa nella porta va sul cinesino di destra della sua stazione; chi riceve in corsa gioca la diagonale e va in fila sul cinesino di sinistra dell’altra stazione.","varianti":"Massimo 2 tocchi, poi 1 tocco. Solo piede debole. Più giocatori per stazione per aumentare i recuperi. Due palloni in contemporanea (uno per stazione).","coaching":"Passaggio forte e preciso nella porta. Set di prima, morbido, sul piede del compagno. Chi riceve parte in anticipo e riceve in corsa con postura aperta verso l’altra stazione. Diagonale tesa e precisa. Tenere il ritmo.","fonte":"Video drill “Pass, set and play” (inviato da Andrea, 23/10/2026)","diagram":{"field":{"preset":"spazio","w":20,"h":12},"steps":[{"title":"Passaggio nella porta","note":"9 passa a 5 tra paletto e manichino"},{"title":"Set","note":"5 appoggia di ritorno nella stessa porta"},{"title":"Fuori dal manichino","note":"9 gioca all’esterno del manichino, 5 riceve in corsa"},{"title":"Diagonale","note":"5 gioca in diagonale a 11 e segue il passaggio; 9 va a destra, 10 entra"},{"title":"Stazione 2: porta","note":"11 passa a 7"},{"title":"Set","note":"7 appoggia di ritorno"},{"title":"Fuori dal manichino","note":"11 gioca all’esterno del manichino, 7 riceve in corsa"},{"title":"Diagonale","note":"7 gioca in diagonale a 10 e segue il passaggio; 11 va a destra, 5 entra"},{"title":"Ricomincia"}],"items":[{"id":"it1101","type":"disc","pos":{"0":{"x":5,"y":0.6}}},{"id":"it1102","type":"disc","pos":{"0":{"x":5,"y":11.4}}},{"id":"it1103","type":"disc","pos":{"0":{"x":15,"y":0.6}}},{"id":"it1104","type":"disc","pos":{"0":{"x":15,"y":11.4}}},{"id":"it1105","type":"pole","pos":{"0":{"x":3.5,"y":6}}},{"id":"it1106","type":"mannequin","pos":{"0":{"x":6.5,"y":6}}},{"id":"it1107","type":"mannequin","pos":{"0":{"x":13.5,"y":6}}},{"id":"it1108","type":"pole","pos":{"0":{"x":16.5,"y":6}}},{"id":"it1109","type":"playerA","label":"9","pos":{"0":{"x":5,"y":3},"4":{"x":5,"y":10.5}}},{"id":"it1110","type":"playerA","label":"10","pos":{"0":{"x":5,"y":1.2},"4":{"x":5,"y":3}}},{"id":"it1111","type":"playerA","label":"5","pos":{"0":{"x":5,"y":10.5},"3":{"x":9,"y":7.9},"4":{"x":15.8,"y":1.2},"8":{"x":15,"y":3}}},{"id":"it1112","type":"playerA","label":"11","pos":{"0":{"x":15,"y":3},"8":{"x":15,"y":10.5}}},{"id":"it1113","type":"playerA","label":"7","pos":{"0":{"x":15,"y":10.5},"7":{"x":11,"y":7.9},"8":{"x":4.2,"y":1.2}}},{"id":"it1114","type":"playerA","label":"6","pos":{"0":{"x":16.6,"y":11.3}}},{"id":"it1115","type":"ball","pos":{"0":{"x":5.5,"y":3.2},"1":{"x":5,"y":9.9},"2":{"x":5.5,"y":3.2},"3":{"x":8.9,"y":7.3},"4":{"x":14.5,"y":3.2},"5":{"x":15,"y":9.9},"6":{"x":14.5,"y":3.2},"7":{"x":11.1,"y":7.3},"8":{"x":5.5,"y":3.2}}}],"arrows":[{"id":"ar1116","kind":"pass","step":0,"from":{"x":5.5,"y":3.2},"to":{"x":5,"y":9.9}},{"id":"ar1117","kind":"pass","step":1,"from":{"x":5,"y":9.9},"to":{"x":5.5,"y":3.2},"curve":0.8},{"id":"ar1118","kind":"pass","step":2,"from":{"x":5.5,"y":3.2},"to":{"x":8.9,"y":7.3},"curve":-2},{"id":"ar1119","kind":"run","step":2,"from":{"x":5,"y":10.5},"to":{"x":9,"y":7.9}},{"id":"ar1120","kind":"pass","step":3,"from":{"x":8.9,"y":7.3},"to":{"x":14.5,"y":3.2}},{"id":"ar1121","kind":"run","step":3,"from":{"x":9,"y":7.9},"to":{"x":15.8,"y":1.2},"curve":1},{"id":"ar1122","kind":"run","step":3,"from":{"x":5,"y":3},"to":{"x":5,"y":10.5},"curve":2.5},{"id":"ar1123","kind":"run","step":3,"from":{"x":5,"y":1.2},"to":{"x":5,"y":3}},{"id":"ar1124","kind":"pass","step":4,"from":{"x":14.5,"y":3.2},"to":{"x":15,"y":9.9}},{"id":"ar1125","kind":"pass","step":5,"from":{"x":15,"y":9.9},"to":{"x":14.5,"y":3.2},"curve":-0.8},{"id":"ar1126","kind":"pass","step":6,"from":{"x":14.5,"y":3.2},"to":{"x":11.1,"y":7.3},"curve":2},{"id":"ar1127","kind":"run","step":6,"from":{"x":15,"y":10.5},"to":{"x":11,"y":7.9}},{"id":"ar1128","kind":"pass","step":7,"from":{"x":11.1,"y":7.3},"to":{"x":5.5,"y":3.2}},{"id":"ar1129","kind":"run","step":7,"from":{"x":11,"y":7.9},"to":{"x":4.2,"y":1.2},"curve":-1},{"id":"ar1130","kind":"run","step":7,"from":{"x":15,"y":3},"to":{"x":15,"y":10.5},"curve":-2.5},{"id":"ar1131","kind":"run","step":7,"from":{"x":15.8,"y":1.2},"to":{"x":15,"y":3}}]},"id":"5eed0000-0000-4000-8000-00000000013e","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = now();
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013f', '{"code":"TEC-23","title":"Pass and press – triangolo","area":"tecnica","fase":["attivazione"],"obiettivi":["passaggio","ricezione","controllo orientato","pressione"],"eta":"U8-U13","giocatori":"4 per triangolo (2 sul cinesino di partenza)","spazio":"Triangolo con lati di 8 m","durata":8,"materiale":"3 cinesini per triangolo, 1 pallone","perche":"Attivazione semplice con tanti passaggi e ricezioni sotto pressione: chi riceve deve controllare e passare con un avversario che arriva forte addosso.","descrizione":"Setup: triangolo di 3 cinesini. A e D sul primo cinesino, B sul secondo, C sul terzo.\nEsecuzione: A passa a B e lo pressa subito, forte. B controlla e passa a C, poi pressa subito C. C passa a D e pressa D, e così via. Chi pressa resta sul cinesino del compagno a cui ha passato: A va sul cinesino di B, B su quello di C, C su quello di partenza.\nSi gira sempre nello stesso verso, senza pause.","rotazione":"Chi passa pressa e prende il posto del compagno a cui ha passato. Dopo 2′ si cambia verso.","varianti":"Due tocchi obbligati (controllo + passaggio), poi un tocco. Controllo orientato lontano dal pressatore. Cambio verso al fischio. Triangolo più piccolo per aumentare la pressione.","coaching":"Passaggio forte e sul piede, poi scatto immediato a pressare. Chi pressa arriva veloce ma frena prima, senza togliere palla. Chi riceve guarda prima il compagno a cui passare, controlla lontano dal pressatore e passa prima che arrivi.","fonte":"Proposta di Andrea (23/10/2026)","diagram":{"field":{"preset":"spazio","w":12,"h":12},"steps":[{"title":"A passa a B","note":"A pressa subito B"},{"title":"B passa a C","note":"B pressa C, A resta sul cinesino di B"},{"title":"C passa a D","note":"C pressa D, B resta sul cinesino di C"},{"title":"D passa ad A","note":"D pressa A, C resta sul cinesino di partenza"},{"title":"A passa a B","note":"A pressa B"},{"title":"B passa a C","note":"B pressa C: tutti hanno cambiato cinesino"},{"title":"Si riparte"}],"items":[{"id":"it1132","type":"disc","pos":{"0":{"x":2,"y":10.6}}},{"id":"it1133","type":"disc","pos":{"0":{"x":10,"y":10.6}}},{"id":"it1134","type":"disc","pos":{"0":{"x":6,"y":3.7}}},{"id":"it1135","type":"playerA","label":"A","pos":{"0":{"x":2,"y":9.5},"1":{"x":8.5,"y":9.5},"2":{"x":10,"y":9.5},"5":{"x":6.75,"y":3.9},"6":{"x":6,"y":2.6}}},{"id":"it1136","type":"playerA","label":"D","pos":{"0":{"x":0.8,"y":10.8},"1":{"x":2,"y":9.5},"4":{"x":8.5,"y":9.5},"5":{"x":10,"y":9.5}}},{"id":"it1137","type":"playerA","label":"B","pos":{"0":{"x":10,"y":9.5},"2":{"x":6.75,"y":3.9},"3":{"x":6,"y":2.6},"6":{"x":2.75,"y":8.2},"7":{"x":0.8,"y":10.8}}},{"id":"it1138","type":"playerA","label":"C","pos":{"0":{"x":6,"y":2.6},"3":{"x":2.75,"y":8.2},"4":{"x":2,"y":9.5}}},{"id":"it1139","type":"ball","pos":{"0":{"x":2.6,"y":9.1},"1":{"x":9.4,"y":9.1},"2":{"x":6.4,"y":3.2},"3":{"x":2.6,"y":9.1},"4":{"x":9.4,"y":9.1},"5":{"x":6.4,"y":3.2},"6":{"x":2.6,"y":9.1}}}],"arrows":[{"id":"ar1140","kind":"pass","step":0,"from":{"x":2.6,"y":9.1},"to":{"x":9.4,"y":9.1}},{"id":"ar1141","kind":"run","step":0,"from":{"x":2,"y":9.5},"to":{"x":8.5,"y":9.5},"curve":-1},{"id":"ar1142","kind":"pass","step":1,"from":{"x":9.4,"y":9.1},"to":{"x":6.4,"y":3.2}},{"id":"ar1143","kind":"run","step":1,"from":{"x":10,"y":9.5},"to":{"x":6.75,"y":3.9},"curve":-1},{"id":"ar1144","kind":"pass","step":2,"from":{"x":6.4,"y":3.2},"to":{"x":2.6,"y":9.1}},{"id":"ar1145","kind":"run","step":2,"from":{"x":6,"y":2.6},"to":{"x":2.75,"y":8.2},"curve":-1},{"id":"ar1146","kind":"pass","step":3,"from":{"x":2.6,"y":9.1},"to":{"x":9.4,"y":9.1}},{"id":"ar1147","kind":"run","step":3,"from":{"x":2,"y":9.5},"to":{"x":8.5,"y":9.5},"curve":-1},{"id":"ar1148","kind":"pass","step":4,"from":{"x":9.4,"y":9.1},"to":{"x":6.4,"y":3.2}},{"id":"ar1149","kind":"run","step":4,"from":{"x":10,"y":9.5},"to":{"x":6.75,"y":3.9},"curve":-1},{"id":"ar1150","kind":"pass","step":5,"from":{"x":6.4,"y":3.2},"to":{"x":2.6,"y":9.1}},{"id":"ar1151","kind":"run","step":5,"from":{"x":6,"y":2.6},"to":{"x":2.75,"y":8.2},"curve":-1}]},"id":"5eed0000-0000-4000-8000-00000000013f","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = now();
